func (l *entryLog) tryCommit(index uint64, term uint64) bool {
	if index <= l.committed {
		return false
	}
	lterm, err := l.term(index)
	if err == ErrCompacted {
		lterm = 0
	} else if err != nil {
		panic(err)
	}
	if index > l.committed && lterm == term {
		l.commitTo(index)
		return true
	}
	return false
}

func (l *entryLog) restore(s pb.Snapshot) {
	l.inmem.restore(s)
	l.committed = s.Index
	l.processed = s.Index
}

