func TestReadIndexLeaderCanBeConfirmed(t *testing.T) {
	r := newReadIndex()
	ctx := getTestSystemCtx(10001)
	ctx2 := getTestSystemCtx(10002)
	ctx3 := getTestSystemCtx(10003)
	r.addRequest(3, ctx2, 1)
