	}
	if ris[1].ctx != ctx {
		t.Errorf("ctx %v, want %v", ris[1].ctx, ctx)
	}
	if ris[0].index != 4 {
		t.Errorf("index %d, want 4", ris[0].index)
	}
	if ris[0].from != 1 {
		t.Errorf("from %d, want 1", ris[0].from)
	}
	if ris[0].ctx != getTestSystemCtx(10002) {
